"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { ArrowDownRight, ArrowUpRight, Minus } from "./icons";

// Stat: generated by UIX from the design system. Same variants and sizes as the Figma component.

const statVariants = cva(
  "flex flex-col gap-2 p-5 bg-surface rounded-xl",
  {
    variants: {
      appearance: {
        outlined: "border border-line-default",
        elevated: "shadow-md",
      },
      trend: {
        up: "[&_[data-slot=trend]]:bg-success-subtle [&_[data-slot=trend]]:text-fg-success",
        down: "[&_[data-slot=trend]]:bg-danger-subtle [&_[data-slot=trend]]:text-fg-danger",
        neutral: "[&_[data-slot=trend]]:bg-subtle [&_[data-slot=trend]]:text-fg-secondary",
      },
    },
    defaultVariants: {
      appearance: "outlined",
      trend: "up",
    },
  },
);

const statIcons = { up: ArrowUpRight, down: ArrowDownRight, neutral: Minus };

export interface StatProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof statVariants> {
  label: React.ReactNode;
  value: React.ReactNode;
  /** Change shown next to the value, for example +12.5%. */
  delta?: React.ReactNode;
  caption?: React.ReactNode;
}

const Stat = React.forwardRef<HTMLDivElement, StatProps>(
  ({ className, appearance, trend, label, value, delta, caption, ...props }, ref) => {
    const Icon = statIcons[trend ?? "up"];
    return (
      <div data-slot="stat" data-kind="surface" ref={ref} className={cn(statVariants({ appearance, trend }), className)} {...props}>
        <p className="text-label-medium text-fg-secondary">{label}</p>
        <div className="flex items-center gap-2">
          <p className="text-heading-3 text-fg-primary">{value}</p>
          {delta ? (
            <span data-slot="trend" className="inline-flex items-center rounded-full gap-0-5 px-1-5 py-0-5 text-label-small">
              <Icon aria-hidden className="size-3" />
              {delta}
            </span>
          ) : null}
        </div>
        {caption ? <p className="text-body-small text-fg-tertiary">{caption}</p> : null}
      </div>
    );
  },
);
Stat.displayName = "Stat";

export { Stat, statVariants };
